import{_ as n,o as i,c as t,a2 as l}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"4.5 电能表与接地电阻测量仪","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-5-dian-neng-biao-yu-jie-di-dian-zu-ce-liang-yi.md","filePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-5-dian-neng-biao-yu-jie-di-dian-zu-ce-liang-yi.md","lastUpdated":1793095197000}'),o={name:"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-5-dian-neng-biao-yu-jie-di-dian-zu-ce-liang-yi.md"};function e(s,a,r,g,h,c){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="_4-5-电能表与接地电阻测量仪" tabindex="-1">4.5 电能表与接地电阻测量仪 <a class="header-anchor" href="#_4-5-电能表与接地电阻测量仪" aria-label="Permalink to &quot;4.5 电能表与接地电阻测量仪&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>这一节介绍两种&quot;记账&quot;和&quot;查隐患&quot;的仪表:电能表(算你家用了多少电、企业耗电多少)和接地电阻测量仪(检查接地装置是否合格)。电能表的接线是实操考核常考内容,重点掌握。</p><h2 id="一、电能表-电度表" tabindex="-1">一、电能表(电度表) <a class="header-anchor" href="#一、电能表-电度表" aria-label="Permalink to &quot;一、电能表(电度表)&quot;">​</a></h2><h3 id="_1-作用与原理" tabindex="-1">1. 作用与原理 <a class="header-anchor" href="#_1-作用与原理" aria-label="Permalink to &quot;1. 作用与原理&quot;">​</a></h3><p><strong>电能表</strong>测量<strong>电能(用电量)</strong>,单位是<strong>千瓦时(kWh)</strong>,就是家里的&quot;电表&quot;。</p><ul><li>常见的是<strong>感应式(机械)电能表</strong>和电子式电能表;</li><li>表内有<strong>电压线圈</strong>(并联在电源上)和<strong>电流线圈</strong>(串联在负载回路中);</li><li>两个线圈的磁场相互作用,推动转盘转动,转盘的圈数与用电量成正比——这就是&quot;计量&quot;的原理。</li></ul><h3 id="_2-单相电能表的直接接线-必会" tabindex="-1">2. 单相电能表的直接接线(必会) <a class="header-anchor" href="#_2-单相电能表的直接接线-必会" aria-label="Permalink to &quot;2. 单相电能表的直接接线(必会)&quot;">​</a></h3><p>单相电能表有 4 个接线端子,常见直接接入方式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>端子1  端子2   端子3  端子4</span></span>
<span class="line"><span>  │      │       │      │</span></span>
<span class="line"><span>火线进  火线出  零线进  零线出</span></span>
<span class="line"><span>(L1进 → L2出→负载) (N3进 → N4出→负载)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>电压线圈:跨接在端子 1 与 3 之间</span></span>
<span class="line"><span>电流线圈:串联在端子 1 与 2 之间</span></span></code></pre></div><p>口诀:<strong>&quot;1 进 2 出接火线,3 进 4 出接零线&quot;</strong>(电压线圈取 1-3 的火零电压)。</p><blockquote><p>⚠️ 实操考核常考:单相电能表接线。核心记住——<strong>电流线圈串接在火线回路,电压线圈并联在火线与零线之间</strong>;火线进 1、出 2,零线进 3、出 4。</p></blockquote><h3 id="_3-电能表的安装要求" tabindex="-1">3. 电能表的安装要求 <a class="header-anchor" href="#_3-电能表的安装要求" aria-label="Permalink to &quot;3. 电能表的安装要求&quot;">​</a></h3><ul><li>电能表应装在<strong>干燥、清洁、无振动</strong>处,便于抄读;</li><li>表箱(柜)要可靠接地;</li><li>电能表回路中应装<strong>熔断器或断路器</strong>作短路保护。</li></ul><h2 id="二、接地电阻测量仪" tabindex="-1">二、接地电阻测量仪 <a class="header-anchor" href="#二、接地电阻测量仪" aria-label="Permalink to &quot;二、接地电阻测量仪&quot;">​</a></h2><h3 id="_1-作用" tabindex="-1">1. 作用 <a class="header-anchor" href="#_1-作用" aria-label="Permalink to &quot;1. 作用&quot;">​</a></h3><p><strong>接地电阻测量仪(接地摇表)<strong>用来测量</strong>接地装置的接地电阻</strong>——接地电阻越小,接地效果越好(合格值一般要求 ≤4 Ω 或 ≤10 Ω,具体见第 11 章)。</p><h3 id="_2-测量要点" tabindex="-1">2. 测量要点 <a class="header-anchor" href="#_2-测量要点" aria-label="Permalink to &quot;2. 测量要点&quot;">​</a></h3><ul><li>测量前<strong>断开被测接地体与电气设备的连接</strong>(脱离电网),避免测量结果受系统影响;</li><li>按仪器说明布设辅助接地极(探针);</li><li>测量时<strong>匀速摇测</strong>(电子式按键测量),读取稳定值;</li><li>测量结果应满足设计要求(接地电阻合格)。</li></ul><h2 id="三、考点提示" tabindex="-1">三、考点提示 <a class="header-anchor" href="#三、考点提示" aria-label="Permalink to &quot;三、考点提示&quot;">​</a></h2><ul><li>✅ 电能表 = 测<strong>电能(kWh)</strong>;电流线圈<strong>串联</strong>、电压线圈<strong>并联</strong>。</li><li>✅ 单相表接线口诀:<strong>1 进 2 出火线、3 进 4 出零线</strong>。</li><li>✅ 接地电阻测量前,先<strong>断开被测接地体与电网的连接</strong>。</li><li>⚠️ 易混点:电能表测&quot;量(度数)&quot;,不是测功率;接地电阻测量仪 ≠ 兆欧表。</li></ul><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><ul><li>电能表计量用电量,靠电压、电流两个线圈;单相接线按&quot;1、2 火,3、4 零&quot;。</li><li>接地电阻测量仪检查接地装置,测量前断开与电网的连接。</li><li>电能表回路要有短路保护,表箱要接地。</li></ul><h2 id="五、自测练习" tabindex="-1">五、自测练习 <a class="header-anchor" href="#五、自测练习" aria-label="Permalink to &quot;五、自测练习&quot;">​</a></h2><ol><li>(单选)电能表是用来测量()的仪表。 A. 电压　B. 电流　C. 电能　D. 功率因数</li><li>(判断)单相电能表的电流线圈应串联在火线回路中。( )</li><li>(单选)单相电能表接线,火线应按()。 A. 1 进 2 出　B. 3 进 4 出　C. 1 进 3 出　D. 2 进 4 出</li><li>(判断)测量接地电阻前,应断开被测接地体与电气设备的连接。( )</li><li>(判断)电能表回路中应设置短路保护(熔断器或断路器)。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>C</strong>。电能表测量电能(用电量),单位 kWh。</li><li><strong>√</strong>。电流线圈串联在火线回路,电压线圈并联。</li><li><strong>A</strong>。口诀:1 进 2 出接火线,3 进 4 出接零线。</li><li><strong>√</strong>。脱离电网才能测得真实接地电阻。</li><li><strong>√</strong>。电能表回路要有短路保护。</li></ol></details>`,26)])])}const p=n(o,[["render",e]]);export{u as __pageData,p as default};
